package ktanesolver.module.modded.regular.maze3;import static org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;class Maze3SolverTest{@Test void routesThroughAllThreeTargets(){BombEntity b=new BombEntity();@SuppressWarnings("unchecked")Maze3Output o=((SolveSuccess<Maze3Output>)new Maze3Solver().solve(new RoundEntity(),b,new ModuleEntity(),new Maze3Input(40,0))).output();assertThat(o.targetFaces()).containsExactly("Magenta","Red","Blue");assertThat(o.commands()).isNotEmpty();assertThat(o.commands().stream().filter("enter"::equals).count()).isEqualTo(3);assertThat(o.commands().getFirst()).isEqualTo("enter");}}
